PhishSense is a phishing-training game built at Emory Hacks 2026 by a team of four (Abigail, Bryan, Ismahan, Yusra). The user does front-end work on the `Abigail_Front_End_Work` branch; PRs go to `main`. Repo: github.com/cardinalcolby/phish-sense. Live on Vercel.

Front-end work done as of 2026-11-14 (in `public/app.js`, `index.html`, `style.css`):
- Mission briefing screen before a run (commit d784c76)
- Feedback animations on Phish/Legit answers, badge reveal, realistic inbox styling, and an end-of-run recap (commit 4067b3c)
- Fish cursor on the home (start) screen only: `public/fish-cursor.js` plus styles at the end of `style.css`. The fish faces its swim direction, wags its tail, leaves a bubble trail and gulps on click; it's off for touch and reduced motion. Added 2026-11-14 and not committed at the end of that session (check `git status`). The user said "like so" but no reference image arrived, so the fish's look may still change.

- Hover-to-inspect links (popup opens above the link, highlights the last two hostname labels) and a "Trusted contacts" directory (Bayline, NewsNow, ConnectPro, TechHub) on the briefing and as a play-screen panel. Commits f39fd0d and 22d1276, pushed 2026-11-14.
- The Gemini prompt lives inline in `askGemini()` in `server.js`; there is no `lib/game.js`/`buildPrompt` (as of 2026-11-14), though the user's requests have referred to one.
- Practice scenarios: every message with a link is a phish, which teaches "link = phish". Adding legit-link scenarios was suggested but not done yet.

**Why:** It's a hackathon, so the user wants polished, demo-ready UI quickly. The README covers the stack and safety rules (fictional Bayline Energy, 555-01xx numbers, no clickable links).
**How to apply:** Build on the existing screens rather than rewriting them, and follow the README safety rules in any new content. Sessions are tracked with Entire ([[entire-session-tracking]]).

function replayAnimation(el) {
  el.style.animation = "none";
  void el.offsetWidth;
  el.style.animation = "";
}

function burstConfetti() {
  const layer = $("confetti");
  layer.innerHTML = "";
  if (calmMode()) return;
  for (let i = 0; i < 30; i++) {
    const bit = document.createElement("span");
    bit.className = "confetti-bit";
    bit.style.left = `${Math.random() * 100}%`;
    bit.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
    bit.style.setProperty("--dx", `${(Math.random() - 0.5) * 240}px`);
    bit.style.setProperty("--rot", `${Math.random() * 900 - 450}deg`);
    bit.style.animationDelay = `${Math.random() * 0.35}s`;
    bit.style.animationDuration = `${1.5 + Math.random()}s`;
    if (i % 3 === 0) bit.style.borderRadius = "50%";
    layer.appendChild(bit);
  }
  setTimeout(() => { layer.innerHTML = ""; }, 3200);
}

function revealBadge(isMaster) {
  const [icon, ...name] = BADGES[mode].split(" ");
  $("badge-art").textContent = icon;
  $("badge-name").textContent = name.join(" ");
  $("badge-reveal").classList.remove("hidden");
  replayAnimation($("badge-art"));
  replayAnimation($("badge-name"));

  if (isMaster) {
    $("badge-master").textContent = "🏆 PhishSense Master: all three badges earned!";
    $("badge-master").classList.remove("hidden");
    replayAnimation($("badge-master"));
  } else {
    $("badge-master").classList.add("hidden");
  }
  burstConfetti();
}

// ---------- End of run ----------
function renderRecap() {
  // Group the same red flag together so repeats show as a count.
  const groups = new Map();
  missed.forEach((flag) => {
    const key = flag.toLowerCase().replace(/\s+/g, " ");
    const hit = groups.get(key);
    if (hit) hit.n++;
    else groups.set(key, { text: flag, n: 1 });
  });
  const items = [...groups.values()].sort((a, b) => b.n - a.n);

  $("recap").innerHTML = `<h3>Red flags you missed this run</h3>` + (items.length
    ? `<ul>${items.map((g) => `<li>${esc(g.text)}${g.n > 1 ? ` <span class="count">×${g.n}</span>` : ""}</li>`).join("")}</ul>`
    : `<p class="clean">You caught every red flag!</p>`);
  $("recap").classList.remove("hidden");
}

async function finish() {
  const passed = correct >= TO_PASS;
  const badge = passed ? mode : null;
  const player = await apiSaveScore($("username").value.trim(), correct * PER_CORRECT, badge);

  const owned = Array.isArray(player?.badges) ? player.badges : (passed ? [mode] : []);
  const isMaster = ALL_MODES.every((m) => owned.includes(m));

  $("end-title").textContent = passed ? `You earned ${BADGES[mode]}!` : `${correct} of ${ROUNDS} correct`;
  $("end-text").textContent = passed
    ? "Nice catch. Try the next mode!"
    : `You need ${TO_PASS} to earn ${BADGES[mode]}. Every round is new, so try again!`;

  if (passed) revealBadge(isMaster);
  else $("badge-reveal").classList.add("hidden");

  renderRecap();
  show("end-screen");
  loadLeaderboard();
}
